          alt: "กราฟแกนนอนแรงดันขดลวด 0 ถึง 15 V ของรีเลย์พิกัด 12 VDC แกนตั้งเป็นสถานะดูดและปล่อย เส้นทึบสีน้ำเงินขาขึ้นอยู่ที่ระดับปล่อยจนถึงประมาณ 8 V แล้วกระโดดขึ้นเป็นดูด เส้นประสีส้มขาลงอยู่ที่ระดับดูดจนลดเหลือประมาณ 3 V จึงตกลงเป็นปล่อย เส้นประแนวตั้งบอกขอบเขต datasheet pull-in ไม่เกิน 9 V และ drop-out ไม่ต่ำกว่า 1.2 V ค่าจริงทั้งสองอยู่ในขอบเขต",
